(()=>{const root=document.getElementById('I03-lab');if(!root)return;const zh=document.documentElement.lang.startsWith('zh'),q=id=>root.querySelector('#I03-'+id),tr=(a,b)=>zh?a:b;let s={fwhm_eV:160,ratio:.5,time_s:30};const listeners=[];function render(){s.area1=6000*s.time_s/30;s.area2=s.area1*s.ratio;s.separation_over_fwhm=140/s.fwhm_eV;s.relative_sd_peak1=1/Math.sqrt(s.area1);q('width').value=s.fwhm_eV;q('ratio').value=s.ratio;q('time').value=s.time_s;const x=Array.from({length:181},(_,i)=>1.6+.005*i),sig=s.fwhm_eV/1000/Math.sqrt(8*Math.log(2));const gs=[2,2.14].map(c=>{const v=x.map(e=>Math.exp(-.5*((e-c)/sig)**2)),sum=v.reduce((a,b)=>a+b,0);return v.map(a=>a/sum)}),ys=x.map((_,i)=>gs[0][i]*s.area1+gs[1][i]*s.area2+8*s.time_s/30),ymax=Math.max(...ys)*1.15;let svg='<rect width="800" height="360" fill="#faf9f5"/><path d="M65 25V305H775" fill="none" stroke="#819095"/>';for(let n=0;n<=4;n++){let y=305-n*65;svg+=`<path d="M65 ${y}H775" stroke="#e0e5e2"/><text x="58" y="${y+4}" text-anchor="end" font-size="12">${(n*ymax/4).toFixed(0)}</text>`}const path=a=>a.map((v,i)=>(i?'L':'M')+(65+i/180*710).toFixed(1)+' '+(305-v/ymax*260).toFixed(1)).join(' ');svg+=`<path d="${path(ys)}" fill="none" stroke="#168477" stroke-width="3"/>`;for(let k=0;k<2;k++)svg+=`<path d="${path(gs[k].map(v=>v*(k?s.area2:s.area1)))}" fill="none" stroke="${k?'#3474a8':'#bd624b'}" stroke-dasharray="6 4" stroke-width="2"/>`;[1.6,1.8,2,2.2,2.4,2.5].forEach(e=>svg+=`<text x="${65+(e-1.6)/.9*710}" y="325" text-anchor="middle" font-size="13">${e.toFixed(1)}</text>`);svg+=`<text x="420" y="350" text-anchor="middle">${tr('能量 / keV','Energy / keV')}</text><text x="75" y="18" font-size="13">${tr('期望计数 / 能道','Expected counts / channel')}</text>`;q('plot').innerHTML=svg;q('result').textContent=tr('峰宽','Width')+` ${s.fwhm_eV} eV · `+tr('面积1 / 2','Area 1 / 2')+` ${s.area1.toFixed(0)} / ${s.area2.toFixed(0)} · `+tr('峰间距 / 峰宽','Separation / FWHM')+` ${s.separation_over_fwhm.toFixed(3)} · `+tr('峰1理想相对标准差','Peak 1 ideal relative SD')+` ${(s.relative_sd_peak1*100).toFixed(2)}%`;}function set(p){if(p.fwhm_eV!==undefined)s.fwhm_eV=Math.min(240,Math.max(80,+p.fwhm_eV));if(p.ratio!==undefined)s.ratio=Math.min(1,Math.max(0,+p.ratio));if(p.time_s!==undefined)s.time_s=Math.min(100,Math.max(10,+p.time_s));render();return {...s}}function on(id,event,fn){q(id).addEventListener(event,fn);listeners.push([q(id),event,fn])}on('width','input',e=>set({fwhm_eV:+e.target.value}));on('ratio','input',e=>set({ratio:+e.target.value}));on('time','input',e=>set({time_s:+e.target.value}));const reset=()=>set({fwhm_eV:160,ratio:.5,time_s:30});on('reset','click',reset);window.CourseLab={set,state:()=>({...s}),reset,destroy:()=>listeners.forEach(([a,b,c])=>a.removeEventListener(b,c))};render();})();
